&lt;p&gt;&lt;span class=&quot;TextRun SCXW246265904 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;Why Valtech?&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;We’re&lt;/span&gt; &lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;the&lt;/span&gt; &lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;experience&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; innovation company &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;- &lt;/span&gt;&lt;span class=&quot;NormalTextRun CommentStart SCXW246265904 BCX0&quot;&gt;a&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; trusted partner&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; to the world’s most recognized brands. To our people we offer &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;growth opportunities, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;a &lt;/span&gt;&lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;values&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;-driven culture, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;international &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;careers&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; and the chance to shape the future of experience.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP CommentStart SCXW246265904 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The opportunity&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Valtech, you’ll find an environment designed for continuous learning, meaningful impact, and professional growth. Whether you&#39;re pioneering new digital solutions, challenging conventional thinking or building the next generation of customer experiences, your work will help transform industries.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are proud of:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/work/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;The work we do and the innovation we drive&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/career/our-values/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Our values of share, care &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;a&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;nd dare&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/valtech-as-workplace/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;A workplace culture that fosters creativity, diversity and autonomy&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/about/offices/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Our borderless, global framework, &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;which enables &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;seamless collaboration&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The role&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p data-start=&quot;846&quot; data-end=&quot;1066&quot;&gt;As a Senior Data Analyst, you are passionate about data-driven transformation and eager to push the boundaries of what’s possible. You bring 5+ years of experience, a growth mindset and a drive to make a lasting impact.&lt;/p&gt;
&lt;p data-start=&quot;1068&quot; data-end=&quot;1109&quot;&gt;You will thrive in this role if you are:&lt;/p&gt;
&lt;ul data-start=&quot;1111&quot; data-end=&quot;1557&quot;&gt;
&lt;li data-section-id=&quot;18vx8di&quot; data-start=&quot;1111&quot; data-end=&quot;1205&quot;&gt;A curious problem solver who can translate business needs into actionable data requirements&lt;/li&gt;
&lt;li data-section-id=&quot;oryr77&quot; data-start=&quot;1206&quot; data-end=&quot;1294&quot;&gt;A self-driven professional who can work autonomously and proactively after onboarding&lt;/li&gt;
&lt;li data-section-id=&quot;1c36844&quot; data-start=&quot;1295&quot; data-end=&quot;1390&quot;&gt;A collaborator who values teamwork and knowledge-sharing across technical and business teams&lt;/li&gt;
&lt;li data-section-id=&quot;19n92fn&quot; data-start=&quot;1391&quot; data-end=&quot;1468&quot;&gt;Excited by the intersection of data, technology and operational excellence&lt;/li&gt;
&lt;li data-section-id=&quot;1lubykk&quot; data-start=&quot;1469&quot; data-end=&quot;1557&quot;&gt;Experienced in Agile methodologies and working within complex enterprise environments&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Role responsibilities&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-section-id=&quot;1aq0110&quot; data-start=&quot;1585&quot; data-end=&quot;1690&quot;&gt;Gather, analyze and document business and data requirements from stakeholders across enterprise domains&lt;/li&gt;
&lt;li data-section-id=&quot;1ixaa9y&quot; data-start=&quot;1691&quot; data-end=&quot;1773&quot;&gt;Manage and prioritize incoming data-related requests, tickets and business needs&lt;/li&gt;
&lt;li data-section-id=&quot;4a8b2c&quot; data-start=&quot;1774&quot; data-end=&quot;1886&quot;&gt;Translate business requirements into clear data requirements to support ingestion and transformation processes&lt;/li&gt;
&lt;li data-section-id=&quot;15fsoxg&quot; data-start=&quot;1887&quot; data-end=&quot;1984&quot;&gt;Support the development and expansion of enterprise-level data products and gold-layer datasets&lt;/li&gt;
&lt;li data-section-id=&quot;9lgrbi&quot; data-start=&quot;1985&quot; data-end=&quot;2121&quot;&gt;Collaborate with data architects, engineers and delivery leads to ensure alignment between business objectives and technical solutions&lt;/li&gt;
&lt;li data-section-id=&quot;vkdwhc&quot; data-start=&quot;2122&quot; data-end=&quot;2222&quot;&gt;Collect and document data quality rules, metadata and catalog descriptions for new data ingestions&lt;/li&gt;
&lt;li data-section-id=&quot;1etnsyn&quot; data-start=&quot;2223&quot; data-end=&quot;2327&quot;&gt;Work with governance and stewardship teams to support data lineage, quality and cataloging initiatives&lt;/li&gt;
&lt;li data-section-id=&quot;1e39ig1&quot; data-start=&quot;2328&quot; data-end=&quot;2413&quot;&gt;Facilitate communication between business stakeholders and technical delivery teams&lt;/li&gt;
&lt;li data-section-id=&quot;1quwynj&quot; data-start=&quot;2414&quot; data-end=&quot;2511&quot;&gt;Contribute to continuous improvement initiatives across data delivery and operational processes&lt;/li&gt;
&lt;li data-section-id=&quot;1dz9y5d&quot; data-start=&quot;2512&quot; data-end=&quot;2593&quot;&gt;Support Agile ceremonies, backlog refinement and workflow management activities&lt;/li&gt;
&lt;li data-section-id=&quot;v8354e&quot; data-start=&quot;2594&quot; data-end=&quot;2712&quot;&gt;Participate in cross-functional discussions related to data modeling, transformation logic and platform capabilities&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Must have qualifications&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p data-start=&quot;2743&quot; data-end=&quot;2829&quot;&gt;To be considered for this role, you must meet the following essential qualifications:&lt;/p&gt;
&lt;ul data-start=&quot;2831&quot; data-end=&quot;3499&quot;&gt;
&lt;li data-section-id=&quot;1iqozti&quot; data-start=&quot;2831&quot; data-end=&quot;2922&quot;&gt;5+ years of experience in data analysis, business analysis or data-focused delivery roles&lt;/li&gt;
&lt;li data-section-id=&quot;lylk9m&quot; data-start=&quot;2923&quot; data-end=&quot;3019&quot;&gt;Experience gathering and documenting business and data requirements in enterprise environments&lt;/li&gt;
&lt;li data-section-id=&quot;1xpwjv&quot; data-start=&quot;3020&quot; data-end=&quot;3095&quot;&gt;Strong understanding of modern data platforms and data lifecycle concepts&lt;/li&gt;
&lt;li data-section-id=&quot;dhh2ov&quot; data-start=&quot;3096&quot; data-end=&quot;3166&quot;&gt;Experience working with Agile methodologies such as SCRUM and Kanban&lt;/li&gt;
&lt;li data-section-id=&quot;3kll78&quot; data-start=&quot;3167&quot; data-end=&quot;3283&quot;&gt;Familiarity with data warehousing concepts, including layered architectures such as bronze, silver and gold models&lt;/li&gt;
&lt;li data-section-id=&quot;14rq8bo&quot; data-start=&quot;3284&quot; data-end=&quot;3401&quot;&gt;Experience collaborating with cross-functional teams including data engineers, architects and business stakeholders&lt;/li&gt;
&lt;li data-section-id=&quot;zkvt1m&quot; data-start=&quot;3402&quot; data-end=&quot;3457&quot;&gt;Strong analytical thinking and problem-solving skills&lt;/li&gt;
&lt;li data-section-id=&quot;u3xgja&quot; data-start=&quot;3458&quot; data-end=&quot;3499&quot;&gt;Excellent command of English (C2 level)&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Nice to have qualifications &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li data-section-id=&quot;qub0y2&quot; data-start=&quot;3535&quot; data-end=&quot;3609&quot;&gt;Experience working with Databricks or similar cloud-based data platforms&lt;/li&gt;
&lt;li data-section-id=&quot;16jkeqz&quot; data-start=&quot;3610&quot; data-end=&quot;3669&quot;&gt;Familiarity with data governance and data quality tooling&lt;/li&gt;
&lt;li data-section-id=&quot;kgbqnz&quot; data-start=&quot;3670&quot; data-end=&quot;3707&quot;&gt;Experience with Jira and Confluence&lt;/li&gt;
&lt;li data-section-id=&quot;qpfkbd&quot; data-start=&quot;3708&quot; data-end=&quot;3776&quot;&gt;Understanding of DBT, Airflow and modern transformation frameworks&lt;/li&gt;
&lt;li data-section-id=&quot;b45u1g&quot; data-start=&quot;3777&quot; data-end=&quot;3838&quot;&gt;Knowledge of conceptual and logical data modeling practices&lt;/li&gt;
&lt;li data-section-id=&quot;1ouvr2m&quot; data-start=&quot;3839&quot; data-end=&quot;3905&quot;&gt;Experience in operational or transportation-related environments&lt;/li&gt;
&lt;li data-section-id=&quot;cz8pyp&quot; data-start=&quot;3906&quot; data-end=&quot;3962&quot;&gt;Strong communication and stakeholder management skills&lt;/li&gt;
&lt;li data-section-id=&quot;8wigeu&quot; data-start=&quot;3963&quot; data-end=&quot;4031&quot;&gt;Ability to work independently in fast-paced, evolving environments&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span class=&quot;TextRun MacChromeBold SCXW105898609 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW105898609 BCX0&quot;&gt;If you do not meet all the listed qualifications or have gaps in your experience, we still encourage you to apply. At Valtech, we recognize that talent comes in many forms, and we value diverse perspectives and a willingness to learn.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW105898609 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;br&gt;Commitment to reaching all kinds of people&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We design experiences that work for all kinds of people - and that starts with our own teams. At Valtech, we’re intentional about building an inclusive culture where everyone feels supported to grow, thrive and achieve their goals. No matter your background, you belong here. &lt;/span&gt;&lt;a href=&quot;https://www.valtech.com/about/diversity-inclusion/&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Explore our Diversity &amp;amp; Inclusion site&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;to see how we’re creating a more equitable Valtech for all.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;br&gt;The benefits &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Beyond a competitive compensation package, we offer:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Flexibility, with hybrid work options and 25 vacation days &lt;/span&gt;for a healthy work-life balance.&lt;/li&gt;
&lt;li&gt;Co-subsidized transportation &amp;amp; Multisport cards.&lt;/li&gt;
&lt;li&gt;Premium health insurance for fast and easy access to top healthcare services.&lt;/li&gt;
&lt;li&gt;Training policy for technical and other skills-related events, courses and certifications.&lt;/li&gt;
&lt;li&gt;Personal career development roadmap guided by performance evaluations.&lt;/li&gt;
&lt;li&gt;Self-care program offering psychological consultations &amp;amp; discussions for you and the team.&lt;/li&gt;
&lt;li&gt;Cozy office space designed for comfort and productivity.&lt;/li&gt;
&lt;li&gt;Exciting team events and company gatherings.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Your application process&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Once you apply, our Talent Acquisition team will review your application. Your CV should cover key information on relevant experiences and expertise. We do not require information such as age, gender, marital status, or a headshot in your application. We review all candidates based on skills, experience, and potential.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;⚠️ Beware of recruitment fraud!&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are committed to inclusion and accessibility. If you need reasonable accommodations during the interview process, please either indicate it in your application or let your Talent Partner know.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About Valtech&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Valtech is the experience innovation company that exists to unlock a better way to experience the world. By blending crafts, categories, and cultures, we help brands unlock new value in an increasingly digital world.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At the intersection of data, AI, creativity, and technology, we drive transformation for leading organizations, including L’Oréal, Mars, Audi, P&amp;amp;G, Volkswagen Dolby, and more.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Valtech, we don’t just talk about transformation. We make it happen. Our people are the heart of our success, and we foster a workplace where everyone has the support to thrive, grow and innovate.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Are you ready to create what’s next? Join us.&lt;/span&gt;&lt;/p&gt;

startx-valtech:greenhouse:4879077101.descriptionHtml:
&lt;p&gt;&lt;span class=&quot;TextRun SCXW246265904 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;&lt;iframe style=&quot;display: table; margin-left: auto; margin-right: auto;&quot; src=&quot;https://www.youtube.com/embed/-v7FHfKa70g&quot; width=&quot;560&quot; height=&quot;314&quot;&gt;&lt;/iframe&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW246265904 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;Why Valtech?&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;We’re&lt;/span&gt; &lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;the&lt;/span&gt; &lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;experience&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; innovation company &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;- &lt;/span&gt;&lt;span class=&quot;NormalTextRun CommentStart SCXW246265904 BCX0&quot;&gt;a&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; trusted partner&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; to the world’s most recognized brands. To our people we offer &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;growth opportunities, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;a &lt;/span&gt;&lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;values&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;-driven culture, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;international &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;careers&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; and the chance to shape the future of experience.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP CommentStart SCXW246265904 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The opportunity&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Valtech, you’ll find an environment designed for continuous learning, meaningful impact, and professional growth. Whether you&#39;re pioneering new digital solutions, challenging conventional thinking or building the next generation of customer experiences, your work will help transform industries.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are proud of:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/work/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;The work we do and the innovation we drive&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/career/our-values/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Our values of share, care &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;a&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;nd dare&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/valtech-as-workplace/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;A workplace culture that fosters creativity, diversity and autonomy&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/about/offices/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Our borderless, global framework, &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;which enables &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;seamless collaboration&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The role&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;As a &lt;strong&gt;&lt;span class=&quot;NormalTextRun SCXW235083899 BCX8&quot;&gt;BUSINESS ANALYST&lt;/span&gt;&lt;/strong&gt;, you are passionate about experience innovation and eager to push the boundaries of what’s possible. You bring&lt;strong&gt; 6+ &lt;/strong&gt;of experience, a growth mindset and a drive to make a lasting impact.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You will thrive in this role if you are:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A curious problem solver who challenges the status quo&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A collaborator who values teamwork and knowledge-sharing&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Excited by the intersection of technology, creativity and data&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experienced in Agile methodologies and consulting (a plus)&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Role responsibilities&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Business Analysis &amp;amp; Requirements&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:100}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:480,&amp;quot;335559991&amp;quot;:240,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Lead end-to-end business analysis for large enterprise data transformation and migration programmes.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:480,&amp;quot;335559991&amp;quot;:240,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Elicit, document, and validate business, functional, and non-functional requirements across data domains including data warehousing, reporting, MDM, and analytics platforms.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:480,&amp;quot;335559991&amp;quot;:240,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Translate complex business problems into well-structured user stories, use cases, process flows, and data mapping documents.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
