&lt;li data-leveltext=&quot;•&quot; data-font=&quot;&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:480,&amp;quot;335559991&amp;quot;:240,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;21&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Hands-on exposure to cloud data platforms such as Google Cloud Platform (GCP), including BigQuery, Dataflow, or Pub/Sub.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:480,&amp;quot;335559991&amp;quot;:240,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;22&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Experience with Databricks (Delta Lake, notebooks, Unity Catalog) in an analytics or data engineering context.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:480,&amp;quot;335559991&amp;quot;:240,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;23&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Familiarity with data mesh&amp;nbsp;architectures, data product thinking, or data contract frameworks.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:480,&amp;quot;335559991&amp;quot;:240,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;24&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Experience in industries such as&amp;nbsp;Manufacturing, Agrotech,&amp;nbsp;BFSI, Retail, or Healthcare where data governance is critical.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span class=&quot;TextRun MacChromeBold SCXW105898609 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW105898609 BCX0&quot;&gt;If you do not meet all the listed qualifications or have gaps in your experience, we still encourage you to apply. At Valtech, we recognize that talent comes in many forms, and we value diverse perspectives and a willingness to learn.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW105898609 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Commitment to reaching all kinds of people&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We design experiences that work for all kinds of people - and that starts with our own teams. At Valtech, we’re intentional about building an inclusive culture where everyone feels supported to grow, thrive and achieve their goals. No matter your background, you belong here. &lt;/span&gt;&lt;a href=&quot;https://www.valtech.com/about/diversity-inclusion/&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Explore our Diversity &amp;amp; Inclusion site&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;to see how we’re creating a more equitable Valtech for all.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&amp;nbsp;&lt;/h3&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The benefits &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This is a fultime position based in &lt;strong&gt;Bengaluru.&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Beyond a competitive compensation package, we offer:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Flexibility, with remote and hybrid work options (country-dependent)&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Career advancement, with international mobility and professional development programs&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Learning and development, with access to cutting-edge tools, training and industry experts&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Our benefits are tailored to each location. Your Talent Partner will provide full details during the hiring process.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Your application process&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Once you apply, our Talent Acquisition team will review your application. Your CV should cover key information on relevant experiences and expertise. We do not require information such as age, gender, marital status, or a headshot in your application. We review all candidates based on skills, experience, and potential.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;⚠️ Beware of recruitment fraud! Only engage with official Valtech email addresses ending in &lt;strong&gt;@valtech.com&lt;/strong&gt;.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are committed to inclusion and accessibility. If you need reasonable accommodations during the interview process, please either indicate it in your application or let your Talent Partner know.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About Valtech&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Valtech is the experience innovation company that exists to unlock a better way to experience the world. By blending crafts, categories, and cultures, we help brands unlock new value in an increasingly digital world.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At the intersection of data, AI, creativity, and technology, we drive transformation for leading organizations, including L’Oréal, Mars, Audi, P&amp;amp;G, Volkswagen Dolby, and more.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Valtech, we don’t just talk about transformation. We make it happen. Our people are the heart of our success, and we foster a workplace where everyone has the support to thrive, grow and innovate.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Are you ready to create what’s next? Join us.&lt;/span&gt;&lt;/p&gt;

threshold-elation-health:greenhouse:7948.descriptionHtml:
&lt;p&gt;Our team is committed to enhancing physician and patient quality of life through Elation, a SaaS cloud-based clinical platform. Since inception, we&#39;ve been focused on building a delightful, world-class experience that empowers physicians to deliver phenomenal care to patients.&lt;/p&gt;
&lt;p&gt;Customer support has been the same job for twenty years: a queue, a ticket, an SLA, a closed case. That&#39;s ending, fast. Over the next 6–9 months, AI will take on more of the routine, repetitive cases at Elation. That doesn&#39;t shrink the human role — it builds on it. The work becomes product intelligence: shaping how AI handles conversations, holding the customer-trust moments that need real judgment, and turning patterns into priorities Engineering delivers.&lt;/p&gt;
&lt;p&gt;We&#39;re hiring &lt;strong&gt;Technical Support&amp;nbsp;Specialists&lt;/strong&gt; to anchor that shift: people who don&#39;t just close tickets, but build the systems that eliminate them, design how AI handles conversations, and turn customer patterns into product priorities.&lt;/p&gt;
&lt;p&gt;You might’ve been the person on a team who builds the dashboards, automations, or workflows that make everyone else better from a Support, Implementation, CS Ops, or Analyst seat. Now you want to formalize that work as the role itself. As a Technical Support Specialist, you&#39;ll bring empathy and judgment to the cases that need it most, own the quality of AI-driven solutions in your domain, and synthesize patterns that influence Product and Engineering roadmaps. We hire for judgment, taste, and curiosity, not process adherence. The bar isn&#39;t &lt;em&gt;how many cases you closed&lt;/em&gt;; it&#39;s &lt;em&gt;how much you reshaped the conditions under which cases happen&lt;/em&gt;.&lt;/p&gt;
&lt;h2&gt;Role and Responsibilities&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Use Good Judgment to Solve Cases.&lt;/strong&gt; Own customer escalations with cases that genuinely require seasoned judgment, the ones AI can&#39;t safely close. Build and protect customer trust in moments that matter.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Build and own AI quality.&lt;/strong&gt; Configure AI within Elation&#39;s stack (intents, knowledge sources, escalation rules), build lightweight external automations, and own the quality of AI outputs in your domain.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Synthesize and partner with Product/Eng.&lt;/strong&gt; Produce formal weekly and monthly insights, participate in roadmap conversations with Product Development teams, and mentor Associates on their build and synthesis work.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;What success looks like in your first 6 months&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Shipped 3–5 AI solutions&lt;/li&gt;
&lt;li&gt;A monthly drumbeat of synthesized insights that Product and Engineering act on, with visible impact on customer experience or a measurable drop in case volume&lt;/li&gt;
&lt;li&gt;Owns a measurable case-volume reduction in your domain by making cases not happen, not by closing them faster&lt;/li&gt;
&lt;li&gt;You question default workflows instead of just executing them, and you ship more by removing work, not just doing more of it.&lt;/li&gt;
&lt;li&gt;You build with AI to make yourself &lt;strong&gt;and the teammates around you&lt;/strong&gt; faster — automating triage, drafting responses, prototyping internal tools, and &lt;strong&gt;turning one-off builds into reusable patterns Associates can run with&lt;/strong&gt;.&lt;/li&gt;
&lt;li&gt;Mentors Associate teammates on AI builds and pattern synthesis&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Professional Qualifications&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;0-4+ years of relevant experience inSupport, Implementation, CS Ops, embedded data analyst, or AI/automation tinkerer in any field.&lt;/li&gt;
&lt;li&gt;A concrete portfolio of things you&#39;ve built or shipped: prompt-engineered systems, dashboards, automations — with evidence of outcomes&lt;/li&gt;
&lt;li&gt;Strong customer-facing communication and trust-building skills&lt;/li&gt;
&lt;li&gt;Pattern recognition and synthesis muscle&lt;/li&gt;
&lt;li&gt;AI-native default. Reaches for AI tools first, treats ambiguity as the work rather than a blocker, and wants to learn how to configure and supervise these systems — not just use them&lt;/li&gt;
&lt;li&gt;A deep desire to drive results for our customers, with high ownership over the outcomes you own&lt;/li&gt;
&lt;li&gt;Curiosity and natural problem-solving instincts&lt;/li&gt;
&lt;li&gt;An instinct to raise the bar for the teammates around you — teaching others to build and synthesize, not just modeling it yourself&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Show us your work&lt;/h2&gt;
&lt;p&gt;Along with your application, in a cover letter send us:&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;2–3 things you&#39;ve built or shipped that changed a metric or outcome — what you made, who it was for, why did you need to do it, and what changed.&lt;/li&gt;
&lt;li&gt;A short story about a time your analysis or insight changed a decision someone else made.&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&lt;strong&gt;Salary range: $52,500 - 75,000 CAD&lt;/strong&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;p&gt;Elation welcomes individuals from all backgrounds and walks of life. Elation is proud to be an Equal Opportunity Employer and is dedicated to creating and maintaining a diverse and inclusive work environment.&lt;/p&gt;
&lt;p&gt;We are committed to equal opportunity for all employees and applicants, and value individuals with diverse perspectives including, but not limited to: race, color, religion, sex, sexual orientation, socioeconomic status, age, gender identity or gender expression, national origin, disability or veteran status.&lt;/p&gt;
&lt;p&gt;Elation also complies with all applicable national, state and local laws governing nondiscrimination in employment as well as work authorization and employment eligibility verification requirements of the Immigration and Nationality Act and IRCA. We firmly believe a strong culture that supports a diverse and inclusive workforce allows us to achieve Elation’s mission of helping independent primary care thrive.&lt;/p&gt;

verdane-wunderflats:greenhouse:484566210.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Here you can find our&amp;nbsp;&lt;a href=&quot;https://boards.eu.greenhouse.io/wunderflatsde&quot; target=&quot;_blank&quot;&gt;German&lt;/a&gt; speaking jobs.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;ABOUT US&lt;br&gt;&lt;br&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;Wunderflats helps people find fully furnished homes for a month or more, perfect for relocations, family moves, or life transitions. It offers a secure and seamless rental experience across Europe.&lt;br&gt;Founded in Berlin in 2015 by Jan Hase and Arkadi Jampolski, Wunderflats bridges the gap between verified landlords and carefully vetted tenants. As part of Europe’s housing infrastructure, it helps activate underutilized apartments and support the evolving ways people live and work today.&lt;/p&gt;
&lt;p&gt;More than 63,000 apartments are currently listed, and the company employs a team of over 150 people.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Learn more at &lt;a href=&quot;https://www.wunderflats.com&quot;&gt;www.wunderflats.com&lt;/a&gt;.&amp;nbsp;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;We are looking for a &lt;strong&gt;Head of Supply Growth &amp;amp; Operations (f/m/d)&lt;/strong&gt; to take full ownership of this engine and evolve it into a &lt;strong&gt;predictable, scalable, and data-driven growth function&lt;/strong&gt;.&lt;/p&gt;
&lt;p&gt;Supply is the core of our marketplace. Every landlord we onboard, every listing we set online, every booking we generate: it starts here. Today, the foundation is there: a functioning funnel, an active sales team, and steady inflow of leads. What’s missing is structure, visibility, and systemization.&lt;/p&gt;
&lt;p&gt;This role is about &lt;strong&gt;professionalizing and scaling what already exists&lt;/strong&gt; — not starting from scratch.&lt;/p&gt;
&lt;p&gt;This is not a traditional sales leadership role. It is a business-critical function with full ownership of supply performance, unit economics, and team development — reporting directly to the VP Operations and working closely with Marketing, Product, Data, and the executive team.&lt;/p&gt;
&lt;p&gt;Does this sound like the right next step in your career? We would like to hear from you.&lt;/p&gt;
&lt;p&gt;&lt;/p&gt;
&lt;h3&gt;YOUR MISSION&lt;/h3&gt;
&lt;p&gt;Own and scale the end-to-end supply growth engine — from lead qualification to first booking, and retention — and turn it into a high-performing system that drives sustainable marketplace growth.&lt;/p&gt;
&lt;h3&gt;End-to-end supply funnel&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Own the overall supply growth engine as well as each funnel stage: lead qualification and prioritisation, conversion, activation, first booking, and retention.&lt;/li&gt;
&lt;li&gt;Define which supply we grow — by quality, geography, and segment — to maximize conversion, efficiency, and customer value. Build a system that consistently turns supply into revenue, not just volume&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Commercial strategy and performance&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Own and drive the KPIs that matter: revenue from new landlords, contribution margin, landlord NPS and time to first booking.&lt;/li&gt;
&lt;li&gt;Build a rigorous understanding of unit economics and supply-side performance drivers that turns data insights into concrete, prioritised, high-impact actions.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;System and process design&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Build and continuously evolve a scalable, data-driven supply operating system that connects all stages of the funnel into one coherent engine.&lt;/li&gt;
&lt;li&gt;Use automation and AI to unlock step-changes in efficiency, customer experience, and growth — not incremental improvements.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Team leadership&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Inspire, lead and develop an amazing sales team of currently 6, with a clear plan to scale to ~8 and beyond through a culture of performance, ownership and accountability grounded in data.&lt;/li&gt;
&lt;li&gt;Build the structure that enables the team to consistently perform at a high level&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Cross-functional collaboration&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Act as the &lt;strong&gt;owner of the supply perspective across the company&lt;/strong&gt;, shaping decisions beyond your immediate scope&lt;/li&gt;
&lt;li&gt;Partner with Marketing, Product, and Data as a &lt;strong&gt;strategic counterpart&lt;/strong&gt;, while staying hands-on where needed&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;YOUR PROFILE&lt;/h3&gt;
&lt;h3&gt;Must-have qualifications&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;7–12 years of experience in marketplace, tech, or high-growth startup and scale-up environments.&lt;/li&gt;
&lt;li&gt;Proven track record in performance optimisation, sales operations, or marketplace growth.&lt;/li&gt;
&lt;li&gt;Strong analytical mindset: you work hands-on with data yourself, not only through analysts.&lt;/li&gt;
&lt;li&gt;Experience managing and developing teams with a clear ownership and accountability culture.&lt;/li&gt;
&lt;li&gt;Fluent in English (C1/C2 required). German is a strong plus.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Preferred qualifications&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Background in consulting with a subsequent transition into an operator role.&lt;/li&gt;
&lt;li&gt;Experience introducing AI or automation into operational workflows.&lt;/li&gt;
&lt;li&gt;Familiarity with supply-side marketplace economics, pricing, or monetisation.&lt;/li&gt;
&lt;li&gt;Experience scaling processes in a 100–200 person organisation.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;What we are really looking for&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;You act like a business owner: full ownership, no excuses, no waiting for perfect conditions.&lt;/li&gt;
&lt;li&gt;You combine structured thinking with pragmatic, hands-on execution — strategy and delivery in one person.&lt;/li&gt;
&lt;li&gt;You are comfortable with ambiguity and energised by building systems from imperfect starting points.&lt;/li&gt;
&lt;li&gt;You embrace modern tooling, AI adoption, and a culture of continuous improvement.&lt;/li&gt;
&lt;li&gt;You can inspire and develop a team while staying genuinely close to the data yourself.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;OUR PITCH&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;div class=&quot;pitch-item&quot;&gt;&lt;strong&gt;#ownershipculture:&lt;/strong&gt;&amp;nbsp;You take full ownership of a critical business function — not a slice of it. Your decisions directly shape revenue, unit economics, and how Wunderflats grows on the supply side.&lt;/div&gt;
&lt;div class=&quot;pitch-item&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div class=&quot;pitch-item&quot;&gt;&lt;strong&gt;#buildsomethingreal:&lt;/strong&gt;&amp;nbsp;This is a rare opportunity to redesign a core growth engine from the inside, bringing structure, automation, and data-driven thinking to a function that is ready for it.&lt;/div&gt;
&lt;div class=&quot;pitch-item&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div class=&quot;pitch-item&quot;&gt;&lt;strong&gt;#careergrowth:&lt;/strong&gt;&amp;nbsp;The role has a clear path toward VP Operations, VP Supply, or General Manager. You will develop general management capabilities, advanced analytics, and AI strategy implementation in a live operational context.&lt;/div&gt;
&lt;div class=&quot;pitch-item&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div class=&quot;pitch-item&quot;&gt;&lt;strong&gt;#empathyculture:&lt;/strong&gt;&amp;nbsp;Become part of our international team with a scale-up atmosphere, where you as a person really count and your ideas and work make a real impact.&lt;/div&gt;
&lt;div class=&quot;pitch-item&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div class=&quot;pitch-item&quot;&gt;&lt;strong&gt;#worklifeinbalance:&lt;/strong&gt;&amp;nbsp;Our working hours are flexible and family-friendly. Three days in our Berlin office, with the option to work from home on the remaining days.&lt;/div&gt;
&lt;div class=&quot;pitch-item&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;div class=&quot;pitch-item&quot;&gt;&lt;strong&gt;#compensationpackage:&lt;/strong&gt;&amp;nbsp;Receive an attractive compensation package and a company pension plan with a 20% employer contribution.&lt;/div&gt;
&lt;div class=&quot;pitch-item&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
